<?php
$client=ins_record($u,$a,(int)$_GET['id']);if($client['kind']!=='clients')throw new DomainException('Client not found.');$c=$client['data'];$cid=(int)$client['id'];
function hub_return(int $cid):void{ihidden('return_client',$cid);}
function hub_form(array $u,array $a,int $cid,string $kind,?array $record=null):void{
    try{ins_allow($u,$a,$kind,'edit');}catch(DomainException){echo '<p class="muted">Read-only access.</p>';return;}$d=$record['data']??[];
    echo '<form method="post" class="form-grid">';iform('save');hub_return($cid);ihidden('kind',$kind);ihidden('id',$record['id']??0);ihidden('version',$record['version']??0);ihidden('client_id',$cid);ihidden('assigned_id',$record['assigned_id']??$u['id']);
    foreach(ins_fields($kind) as $key=>$type){$v=$d[$key]??'';if($type==='money')ifield($key,'number',$v!==''?$v/100:'');elseif($type==='frequency'){$opts=['once','weekly','monthly','quarterly','half-yearly','yearly'];iselect($key,array_combine($opts,$opts),$v?:'once');}elseif($type==='category')iselect($key,array_combine($a['settings']['categories'],$a['settings']['categories']),$v);elseif(str_starts_with($type,'select:')){$opts=explode(',',substr($type,7));iselect($key,array_combine($opts,$opts),$v?:$opts[0]);}else ifield($key,$type,$v);}
    echo '<button>Save '.ie($kind==='clients'?'client':'record').'</button></form>';
}
?>
<a class="back-link" href="<?=ie(iu('clients'))?>">← All clients</a>
<section class="panel client-heading"><div class="section-head"><div><span class="eyebrow">CLIENT OVERVIEW</span><h2><?=ie($c['name'])?></h2><p><?=ie($c['city']??'')?> · <?=ie($c['email']?:'No email recorded')?> · <?=ie($c['phone']?:'No phone recorded')?></p></div><span class="badge"><?=$client['archived']?'Archived':'Client'?></span></div>
<div class="form-grid"><div><h3>Contact details</h3><p><?=nl2br(ie($c['address']?:'No address recorded'))?> <?=ie($c['pincode'])?></p><p>Date of birth: <?=ie($c['dob']?:'Not recorded')?></p><p>Source: <?=ie($c['source']?:'Not recorded')?> · Tags: <?=ie($c['tags']?:'None')?></p></div><div><h3>Family & notes</h3><p><?=nl2br(ie($c['family']?:'No family details yet'))?></p><p><?=nl2br(ie($c['notes']))?></p></div></div>
<div class="actions"><?php if($c['phone']):?><a class="button secondary" href="tel:<?=ie(preg_replace('/[^+0-9]/','',$c['phone']))?>">Call</a><?php endif ?><?php if($c['email']&&in_array($c['consent'],['email','both'],true)):?><a class="button secondary" href="mailto:<?=ie($c['email'])?>">Compose email</a><?php endif ?></div>
